import type { CSSProperties, SVGProps } from "react";

/**
 * Tiles & Finishes subcategory icons — converted from the client's
 * isometric/material-rendered SVG set (surfaces/*.svg). Unlike the
 * single-color line packs (Lighting, Furniture, Home Décor), these keep
 * their own literal gradient/material colors, so there is no currentColor
 * theming here — only the shared ".sf" stroke/fill defaults and hover
 * animations driven by the semantic classes already present in the source
 * markup (row, tile, drop, rip, lit, shine, roll, t, h, m, p).
 */

type IconProps = SVGProps<SVGSVGElement>;

const mergeClass = (base: string, extra?: string) => [base, extra].filter(Boolean).join(" ");

export const TilesFinishesIconStyles = () => (
  <style>{`
svg.sf{width:100%;height:100%;overflow:visible;fill:none;stroke:#25282c;stroke-width:3.5;stroke-linejoin:round;stroke-linecap:round;transition:filter .35s}
svg.sf:hover{filter:drop-shadow(0 2px 5px rgba(0,0,0,.25))}
@keyframes sfrow{0%,100%{transform:translateX(0)}50%{transform:translateX(var(--d,0px))}}
svg.sf:hover .row{animation:sfrow 2.6s ease-in-out infinite}
@keyframes sfpop{0%{opacity:.35;transform:scale(.88)}100%{opacity:1;transform:scale(1)}}
svg.sf:hover .h,svg.sf:hover .t,svg.sf:hover .p,svg.sf:hover .t.fb{animation:sfpop .5s ease-out both}
@keyframes sfsweep{0%{transform:translateX(-10%)}100%{transform:translateX(10%)}}
svg.sf:hover .shine{animation:sfsweep 1.6s ease-in-out infinite alternate}
@keyframes sflit{0%{opacity:0}45%{opacity:1}100%{opacity:1}}
svg.sf:hover .lit{animation:sflit .9s ease forwards}
@keyframes sfstack{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}
svg.sf:hover .a{animation:sfstack 1.8s ease-in-out infinite}
svg.sf:hover .b{animation:sfstack 1.8s ease-in-out infinite .15s}
svg.sf:hover .c{animation:sfstack 1.8s ease-in-out infinite .3s}
@keyframes sfdrop{0%{opacity:0;transform:translate(130px,18px) scale(.7)}12%{opacity:1}55%{opacity:1;transform:translate(130px,82px) scale(1)}60%,100%{opacity:0;transform:translate(130px,82px) scale(1)}}
svg.sf:hover .drop{animation:sfdrop 1.3s ease-in infinite}
@keyframes sfripple{0%,52%{opacity:0;transform:scale(.3)}60%{opacity:.85;transform:scale(.6)}100%{opacity:0;transform:scale(1.8)}}
svg.sf:hover .rip{transform-origin:130px 88px;animation:sfripple 1.3s ease-out infinite}
svg.sf:hover .rip.r2{animation-delay:.15s}
@keyframes sfroll{to{transform:rotate(360deg)}}
svg.sf:hover .roll{transform-origin:105px 167px;animation:sfroll 4s linear infinite}
`}</style>
);

